using System.Text.Json.Nodes;
using TouhouLastWorld;

internal sealed partial class RegressionSuite
{
    private void Scenario02()
    {
        Check(teams.Dispatch("home_select_unit_update", arguments: new(Value: 1)).Status == 400 && teams.Dispatch("home_select_unit_update", arguments: new(Value: -1)).Status == 400, "home selection bounds");
        Check(teams.Dispatch("home_select_unit_update", arguments: new(Value: 0)).Body!["user_update"]!["home_unit_info"]!["select_unit_index"]!.GetValue<int>() == 0, "home selection saved");
        Check(teams.Dispatch("home_bgm_update", arguments: new(Value: -2)).Status == 400, "invalid negative home music rejected");
        Check(teams.Dispatch("home_bgm_update", arguments: new(Value: -1)).Body!["user_update"]!["select_bgm"]!.GetValue<int>() == -1, "home music can be turned off");
        Check(teams.Dispatch("home_bgm_update", arguments: new(Value: 123)).Status == 0, "home music saved");
        Check(teams.Dispatch("unit_bgm_update", arguments: new(999, 123)).Status == 404, "unit music requires owned unit");
        Check(teams.Dispatch("unit_bgm_update", arguments: new(1, -2)).Status == 400, "invalid negative unit music rejected");
        Check(teams.Dispatch("unit_bgm_update", arguments: new(1, -1)).Body!["user_update"]!["unit"]!["unit_list"]![0]!["select_bgm"]!.GetValue<int>() == -1, "unit music can be turned off");
        Check(teams.Dispatch("unit_bgm_update", arguments: new(1, 456)).Status == 0, "unit music saved");
        var homeReload = new OfflineServer(new JsonStateStore(teamDirectory), teamSeed.ToJsonString(), "offline://resources/");
        homeReload.Dispatch("game_init");
        var homeUser = homeReload.Dispatch("login").Body!["user"]!;
        Check(homeUser["select_bgm"]!.GetValue<int>() == 123 && homeUser["unit"]!["unit_list"]![0]!["select_bgm"]!.GetValue<int>() == 456 && homeUser["bgm_item"]!["received_bgm_item_id_list"]!.AsArray().Count == 0, "music preferences persist without granting items");
        Check(homeReload.Dispatch("home_bgm_update", arguments: new(Value: 0)).Body!["user_update"]!["select_bgm"]!.GetValue<int>() == 0, "home music default restored");
        Console.WriteLine("Passed 10 home preference checks.");
        var homeEntry = new LocalHomeEntry(1001, 1, 100101, 0, 123);
        Check(teams.Dispatch("favorite_unit_update", arguments: new(Home: new([], 0, 0))).Status == 400, "home requires an entry");
        Check(teams.Dispatch("favorite_unit_update", arguments: new(Home: new([homeEntry], 1, 0))).Status == 400, "home configuration selection bounds");
        Check(teams.Dispatch("favorite_unit_update", arguments: new(Home: new([homeEntry], 0, 2))).Status == 400, "home random mode bounds");
        Check(teams.Dispatch("favorite_unit_update", arguments: new(Home: new([homeEntry with { UserUnitId = 999 }], 0, 0))).Status == 404, "home configuration ownership");
        Check(teams.Dispatch("favorite_unit_update", arguments: new(Home: new([homeEntry with { UnitId = 999 }], 0, 0))).Status == 400, "home identifiers must match");
        Check(teams.Dispatch("favorite_unit_update", arguments: new(Home: new([homeEntry with { Music = -2 }], 0, 0))).Status == 400, "invalid negative layout music rejected");
        var configuredHome = teams.Dispatch("favorite_unit_update", arguments: new(Home: new([homeEntry with { Music = -1 }], 0, 1))).Body!["user_update"]!["home_unit_info"]!;
        Check(configuredHome["random_select_mode"]!.GetValue<int>() == 1 && configuredHome["unit_param"]![0]!["bgm"]!.GetValue<int>() == -1, "complete home configuration saved");
        var beforeInvalidHome = teams.Dispatch("login").Body!["user"]!["home_unit_info"]!.DeepClone();
        Check(teams.Dispatch("favorite_unit_update", arguments: new(Home: new([homeEntry, homeEntry with { UserUnitId = 999 }], 0, 0))).Status == 404 && JsonNode.DeepEquals(beforeInvalidHome, teams.Dispatch("login").Body!["user"]!["home_unit_info"]), "home batch update is atomic");
        Check(teams.Dispatch("update_home_motion_mode", arguments: new(999, 1)).Status == 404 && teams.Dispatch("update_home_motion_mode", arguments: new(1, -1)).Status == 400, "motion preference validates target and value");
        Check(teams.Dispatch("update_home_motion_mode", arguments: new(1, 1)).Status == 0, "motion preference saved");
        var configuredHomeReload = new OfflineServer(new JsonStateStore(teamDirectory), teamSeed.ToJsonString(), "offline://resources/");
        configuredHomeReload.Dispatch("game_init");
        var configuredUser = configuredHomeReload.Dispatch("login").Body!["user"]!;
        Check(configuredUser["home_unit_info"]!["random_select_mode"]!.GetValue<int>() == 1 && configuredUser["home_unit_info"]!["unit_param"]![0]!["bgm"]!.GetValue<int>() == -1 && configuredUser["unit"]!["unit_list"]![0]!["home_motion"]!.GetValue<int>() == 1, "home configuration and motion persist");
        Console.WriteLine("Passed 11 home configuration checks.");
        Check(flags.Dispatch("anniversary_info_get").Body!["mail_address"]!.GetValue<string>() == "", "empty anniversary contact");
        var personal = flags.Dispatch("personal_info_get").Body!;
        Check(new[] { "user_name", "zip_code", "address", "phone_number" }.All(field => personal[field]!.GetValue<string>() == ""), "empty personal contact fields");
        var ranking = flags.Dispatch("get_series_battle_ranking_list").Body!;
        Check(ranking["ranking"]!.AsArray().Count == 0 && ranking["myrank"]!.AsArray().Count == 0, "no fabricated ranking");
        var gauge = flags.Dispatch("get_raid_gauge").Body!;
        Check(gauge["raid_gauge_list"]!.AsArray().Count == 0, "empty shared progress list");
        gauge["raid_gauge_list"]!.AsArray().Add(new JsonObject());
        Check(flags.Dispatch("get_raid_gauge").Body!["raid_gauge_list"]!.AsArray().Count == 0, "query templates remain isolated");
        Console.WriteLine("Passed 5 contact and progress query checks.");
        var mailSeed = JsonNode.Parse(seed)!.AsObject();
        mailSeed["_local_mail"] = new JsonArray(new JsonObject { ["id"] = 1, ["open_type"] = 0 }, new JsonObject { ["id"] = 2, ["open_type"] = 1 });
        var mailDirectory = directory + "-mail";
        var mailbox = new OfflineServer(new JsonStateStore(mailDirectory), mailSeed.ToJsonString(), "offline://resources/");
        mailbox.Dispatch("game_init");
        mailbox.Dispatch("login");
        Check(mailbox.Dispatch("mail_top").Body!["mail"]!.AsArray().Count == 2, "mail overview reads local records");
        var remainingMail = mailbox.Dispatch("mail_delete").Body!["mail"]!.AsArray();
        Check(remainingMail.Count == 1 && remainingMail[0]!["id"]!.GetValue<int>() == 1, "deletion preserves unread mail");
        Check(mailbox.Dispatch("mail_delete").Body!["mail"]!.AsArray().Count == 1, "mail deletion is idempotent");
        Check(mailbox.Dispatch("read_unit_talk", arguments: new(Value: -1)).Status == 400, "invalid talk ID rejected");
        Check(mailbox.Dispatch("read_unit_talk", arguments: new(Value: 12)).Status == 0 && mailbox.Dispatch("read_unit_talk", arguments: new(Value: 12)).Status == 0, "talk read is idempotent");
        var mailReload = new OfflineServer(new JsonStateStore(mailDirectory), mailSeed.ToJsonString(), "offline://resources/");
        mailReload.Dispatch("game_init");
        var mailUser = mailReload.Dispatch("login").Body!["user"]!;
        Check(mailReload.Dispatch("mail_top").Body!["mail"]!.AsArray().Count == 1, "mail deletion persists");
        Check(mailUser["_local_read_talk_ids"]!.AsArray().Count == 1 && mailUser["_local_read_talk_ids"]![0]!.GetValue<int>() == 12, "read marker persists without duplicates");
        Console.WriteLine("Passed 7 mail and talk checks.");
        Check(mailbox.Dispatch("unit_voice_update", arguments: new(1001, -1)).Status == 400, "negative voice selection rejected");
        Check(mailbox.Dispatch("unit_voice_update", arguments: new(999999, 1)).Status == 404, "unknown collection unit rejected");
        var voiceAlbum = mailbox.Dispatch("unit_voice_update", arguments: new(1001, 23)).Body!["user_update"]!["album"]!;
        Check(voiceAlbum["unit_list"]![0]!["voice_set_id"]!.GetValue<int>() == 23, "voice selection stored in album");
        Check(mailbox.Dispatch("unit_voice_update", arguments: new(1001, 0)).Status == 0, "default voice selection accepted");
        var voiceReload = new OfflineServer(new JsonStateStore(mailDirectory), mailSeed.ToJsonString(), "offline://resources/");
        voiceReload.Dispatch("game_init");
        var voiceUser = voiceReload.Dispatch("login").Body!["user"]!;
        Check(voiceUser["album"]!["unit_list"]!.AsArray().Count == 1 && voiceUser["album"]!["unit_list"]![0]!["voice_set_id"]!.GetValue<int>() == 0, "voice preference persists without duplicate entries");
        var beforeTelemetry = voiceUser.DeepClone();
        Check(voiceReload.Dispatch("transcribe_kpi", arguments: new(Value: 1)).Status == 0 && voiceReload.Dispatch("transcribe_kpi", arguments: new(Value: 2)).Status == 0, "known telemetry events accepted");
        Check(voiceReload.Dispatch("transcribe_kpi", arguments: new(Value: 3)).Status == 400, "unknown telemetry event rejected");
        Check(JsonNode.DeepEquals(beforeTelemetry, voiceReload.Dispatch("login").Body!["user"]), "telemetry does not mutate user state");
        Console.WriteLine("Passed 8 voice and telemetry checks.");
        var facilitySeed = JsonNode.Parse(seed)!.AsObject();
        facilitySeed["unit"]!["unit_list"]![0]!["is_lecture"] = 1;
        facilitySeed["lecture_room"]!["unit"]!["unit_list"]!.AsArray().Add(new JsonObject { ["user_unit_id"] = 1L, ["put_trust_up_icon"] = 0 });
        var facilityDirectory = directory + "-facilities";
        var facilities = new OfflineServer(new JsonStateStore(facilityDirectory), facilitySeed.ToJsonString(), "offline://resources/");
        facilities.Dispatch("game_init");
        facilities.Dispatch("login");
        Check(facilities.Dispatch("lecture_room_unit_remove", arguments: new(EntityId: 0)).Status == 400, "invalid facility member rejected");
        Check(facilities.Dispatch("lecture_room_unit_remove", arguments: new(EntityId: 999)).Status == 404, "facility removal requires owned unit");
        var snapshot = facilities.Dispatch("lecture_room_update").Body!;
        Check(snapshot["user_update"]!["lecture_room"]!["unit"]!["unit_list"]!.AsArray().Count == 1 && snapshot["spend_info"]!["exp"]!.GetValue<int>() == 0, "facility snapshot preserves members without fabricated earnings");
        var removed = facilities.Dispatch("lecture_room_unit_remove", arguments: new(EntityId: 1)).Body!["user_update"]!;
        Check(removed["lecture_room"]!["unit"]!["unit_list"]!.AsArray().Count == 0 && removed["unit"]!["unit_list"]![0]!["is_lecture"]!.GetValue<int>() == 0, "facility removal clears membership and flag");
        Check(facilities.Dispatch("lecture_room_unit_remove", arguments: new(EntityId: 1)).Status == 0, "facility removal is idempotent");
        var facilityReload = new OfflineServer(new JsonStateStore(facilityDirectory), facilitySeed.ToJsonString(), "offline://resources/");
        facilityReload.Dispatch("game_init");
        var facilityUser = facilityReload.Dispatch("login").Body!["user"]!;
        Check(facilityUser["lecture_room"]!["unit"]!["unit_list"]!.AsArray().Count == 0 && facilityUser["unit"]!["unit_list"]![0]!["is_lecture"]!.GetValue<int>() == 0, "facility removal persists");
        Check(JsonNode.DeepEquals(facilitySeed["lecture_room"]!["food"], facilityUser["lecture_room"]!["food"]), "removal preserves food state");
        Console.WriteLine("Passed 7 facility checks.");
        Check(facilityReload.Dispatch("lecture_room_unit_set", arguments: new(1)).Status == 503, "joining requires resolved capacity");
        Check(facilityReload.Dispatch("lecture_room_unit_set", arguments: new(999, 1)).Status == 404, "joining requires ownership");
        var joined = facilityReload.Dispatch("lecture_room_unit_set", arguments: new(1, 1)).Body!["user_update"]!;
        Check(joined["lecture_room"]!["unit"]!["unit_list"]!.AsArray().Count == 1 && joined["unit"]!["unit_list"]![0]!["is_lecture"]!.GetValue<int>() == 1, "joining updates membership and flag");
        Check(facilityReload.Dispatch("lecture_room_unit_set", arguments: new(1, 1)).Body!["user_update"]!["lecture_room"]!["unit"]!["unit_list"]!.AsArray().Count == 1, "repeated joining does not duplicate members");
        var joinedReload = new OfflineServer(new JsonStateStore(facilityDirectory), facilitySeed.ToJsonString(), "offline://resources/");
        joinedReload.Dispatch("game_init");
        Check(joinedReload.Dispatch("login").Body!["user"]!["unit"]!["unit_list"]![0]!["is_lecture"]!.GetValue<int>() == 1, "joining persists");
        var fullSeed = facilitySeed.DeepClone().AsObject();
        var secondUnit = fullSeed["unit"]!["unit_list"]![0]!.DeepClone();
        secondUnit["user_unit_id"] = 2L;
        secondUnit["is_lecture"] = 0;
        fullSeed["unit"]!["unit_list"]!.AsArray().Add(secondUnit);
        var fullFacility = new OfflineServer(new JsonStateStore(directory + "-full-facility"), fullSeed.ToJsonString(), "offline://resources/");
        fullFacility.Dispatch("game_init");
        fullFacility.Dispatch("login");
        Check(fullFacility.Dispatch("lecture_room_unit_set", arguments: new(2, 1)).Status == 409 && fullFacility.Dispatch("login").Body!["user"]!["unit"]!["unit_list"]![1]!["is_lecture"]!.GetValue<int>() == 0, "full facility rejects without mutation");
        Console.WriteLine("Passed 6 facility joining checks.");
        var expansionSeed = JsonNode.Parse(seed)!.AsObject();
        expansionSeed["orb"]!["free"] = 3;
        expansionSeed["orb"]!["purchased"] = 7;
        var expansionDirectory = directory + "-expansion";
        var expansion = new OfflineServer(new JsonStateStore(expansionDirectory), expansionSeed.ToJsonString(), "offline://resources/");
        expansion.Dispatch("game_init");
        expansion.Dispatch("login");
        Check(expansion.Dispatch("lecture_room_unit_expansion").Status == 503, "missing expansion data rejected");
        Check(expansion.Dispatch("lecture_room_unit_expansion", arguments: new(2, 1)).Status == 409, "expansion cannot skip levels");
        Check(expansion.Dispatch("lecture_room_unit_expansion", arguments: new(1, 11)).Status == 409 && expansion.LectureExpansionRank == 0, "insufficient expansion funds preserve level");
        var expanded = expansion.Dispatch("lecture_room_unit_expansion", arguments: new(1, 5)).Body!["user_update"]!;
        Check(expanded["orb"]!["free"]!.GetValue<long>() == 0 && expanded["orb"]!["purchased"]!.GetValue<long>() == 5 && expansion.LectureExpansionRank == 1, "expansion debits free balance first and updates level");
        Check(expansion.Dispatch("lecture_room_unit_expansion", arguments: new(1, 5)).Status == 409, "stale expansion quote rejected");
        var expansionReload = new OfflineServer(new JsonStateStore(expansionDirectory), expansionSeed.ToJsonString(), "offline://resources/");
        expansionReload.Dispatch("game_init");
        Check(expansionReload.Dispatch("login").Body!["user"]!["orb"]!["purchased"]!.GetValue<long>() == 5 && expansionReload.LectureExpansionRank == 1, "expansion debit and level persist together");
        Console.WriteLine("Passed 6 facility expansion checks.");
        Check(expansionReload.Dispatch("lecture_room_food_expansion", arguments: new(1, 6)).Status == 409 && expansionReload.LectureFoodExpansionRank == 0, "food expansion requires funds");
        var foodExpanded = expansionReload.Dispatch("lecture_room_food_expansion", arguments: new(1, 2)).Body!["user_update"]!;
        Check(expansionReload.LectureFoodExpansionRank == 1 && expansionReload.LectureExpansionRank == 1 && foodExpanded["orb"]!["purchased"]!.GetValue<long>() == 3, "food expansion has independent level and shared balance");
        Check(foodExpanded["lecture_room"]!["food"]!["food_rest_value"]!.GetValue<int>() == 0, "food expansion does not grant food");
        var foodExpansionReload = new OfflineServer(new JsonStateStore(expansionDirectory), expansionSeed.ToJsonString(), "offline://resources/");
        foodExpansionReload.Dispatch("game_init");
        Check(foodExpansionReload.Dispatch("login").Body!["user"]!["orb"]!["purchased"]!.GetValue<long>() == 3 && foodExpansionReload.LectureFoodExpansionRank == 1, "food expansion persists with debit");
        Console.WriteLine("Passed 4 food expansion checks.");
        Check(foodExpansionReload.Dispatch("training_room_expansion", arguments: new(1, 4)).Status == 409, "training expansion requires sufficient funds");
        var trainingExpanded = foodExpansionReload.Dispatch("training_room_expansion", arguments: new(1, 2)).Body!["user_update"]!;
        Check(trainingExpanded["orb"]!["purchased"]!.GetValue<long>() == 1 && foodExpansionReload.TrainingExpansionRank == 1 && foodExpansionReload.LectureFoodExpansionRank == 1, "training expansion updates its own level and balance");
        var trainingSnapshot = foodExpansionReload.Dispatch("training_room_update").Body!["user_update"]!["training_room"]!;
        Check(trainingSnapshot["expansion_rank"]!.GetValue<int>() == 1 && trainingSnapshot["unit_list"]!.AsArray().Count == 0, "training snapshot reads saved state");
        trainingSnapshot["expansion_rank"] = 99;
        Check(foodExpansionReload.TrainingExpansionRank == 1, "training snapshot is isolated");
        var trainingReload = new OfflineServer(new JsonStateStore(expansionDirectory), expansionSeed.ToJsonString(), "offline://resources/");
        trainingReload.Dispatch("game_init");
        Check(trainingReload.Dispatch("login").Body!["user"]!["orb"]!["purchased"]!.GetValue<long>() == 1 && trainingReload.TrainingExpansionRank == 1, "training expansion and payment persist");
        Console.WriteLine("Passed 5 training facility checks.");
        var cancelSeed = JsonNode.Parse(seed)!.AsObject();
        cancelSeed["training_room"]!["unit_list"] = new JsonArray(new JsonObject { ["slot_number"] = 1, ["user_unit_id"] = 1L, ["skill_number"] = 1 }, new JsonObject { ["slot_number"] = 2, ["user_unit_id"] = 2L, ["skill_number"] = 2 });
        var cancelDirectory = directory + "-cancel";
        var cancel = new OfflineServer(new JsonStateStore(cancelDirectory), cancelSeed.ToJsonString(), "offline://resources/");
        cancel.Dispatch("game_init");
        var beforeTrainingCancel = cancel.Dispatch("login").Body!["user"]!;
        Check(cancel.Dispatch("training_room_cancel", arguments: new(Value: 0)).Status == 400, "zero training slot rejected");
        Check(cancel.Dispatch("training_room_cancel", arguments: new(Value: 3)).Status == 404, "missing training task rejected");
        var remainingTraining = cancel.Dispatch("training_room_cancel", arguments: new(Value: 1)).Body!["user_update"]!["training_room"]!["unit_list"]!.AsArray();
        Check(remainingTraining.Count == 1 && remainingTraining[0]!["slot_number"]!.GetValue<int>() == 2, "cancellation removes only requested task");
        Check(cancel.Dispatch("training_room_cancel", arguments: new(Value: 1)).Status == 404, "cancelled slot is empty");
        var cancelReload = new OfflineServer(new JsonStateStore(cancelDirectory), cancelSeed.ToJsonString(), "offline://resources/");
        cancelReload.Dispatch("game_init");
        var cancelledUser = cancelReload.Dispatch("login").Body!["user"]!;
        Check(cancelledUser["training_room"]!["unit_list"]!.AsArray().Count == 1, "cancellation persists");
        Check(JsonNode.DeepEquals(beforeTrainingCancel["unit"], cancelledUser["unit"]) && JsonNode.DeepEquals(cancelSeed["orb"], cancelledUser["orb"]), "cancellation does not grant growth or currency");
        Console.WriteLine("Passed 6 training cancellation checks.");
        equipmentSeed = JsonNode.Parse(seed)!.AsObject();
        equipmentSeed["unit"]!["unit_list"]![0]!["equip_spellcard1_user_picture_id"] = 11L;
        equipmentSeed["picture"]!["picture_list"] = new JsonArray(new JsonObject { ["user_picture_id"] = 11L, ["equip_user_unit_id"] = 1L, ["is_protection"] = 1 }, new JsonObject { ["user_picture_id"] = 12L, ["equip_user_unit_id"] = 2L, ["is_protection"] = 0 });
        equipmentDirectory = directory + "-equipment";
        var equipment = new OfflineServer(new JsonStateStore(equipmentDirectory), equipmentSeed.ToJsonString(), "offline://resources/");
        equipment.Dispatch("game_init");
        equipment.Dispatch("login");
        Check(equipment.Dispatch("unit_equip_picture_reset", arguments: new(EntityId: 0)).Status == 400, "equipment reset requires positive ID");
        Check(equipment.Dispatch("unit_equip_picture_reset", arguments: new(EntityId: 999)).Status == 404, "equipment reset requires ownership");
        var resetEquipment = equipment.Dispatch("unit_equip_picture_reset", arguments: new(EntityId: 1)).Body!["user_update"]!;
        Check(Enumerable.Range(1, 5).All(slot => resetEquipment["unit"]!["unit_list"]![0]![$"equip_spellcard{slot}_user_picture_id"]!.GetValue<long>() == 0), "all equipment slots cleared");
        Check(resetEquipment["picture"]!["picture_list"]![0]!["equip_user_unit_id"]!.GetValue<long>() == 0 && resetEquipment["picture"]!["picture_list"]![0]!["is_protection"]!.GetValue<int>() == 1 && resetEquipment["picture"]!["picture_list"]![1]!["equip_user_unit_id"]!.GetValue<long>() == 2, "reverse link cleared without changing protection or other owners");
        Check(equipment.Dispatch("unit_equip_picture_reset", arguments: new(EntityId: 1)).Status == 0, "equipment reset is idempotent");
        equipmentReload = new OfflineServer(new JsonStateStore(equipmentDirectory), equipmentSeed.ToJsonString(), "offline://resources/");
        equipmentReload.Dispatch("game_init");
        var equipmentUser = equipmentReload.Dispatch("login").Body!["user"]!;
        Check(equipmentUser["unit"]!["unit_list"]![0]!["equip_spellcard1_user_picture_id"]!.GetValue<long>() == 0 && equipmentUser["picture"]!["picture_list"]![0]!["equip_user_unit_id"]!.GetValue<long>() == 0, "both equipment references persist together");
        Console.WriteLine("Passed 6 equipment reset checks.");
    }
}
